{"function":"async () => {
  const h = document.body.scrollHeight;
  for (let y = 0; y <= h; y += 500) {
    window.scrollTo(0, y);
    await new Promise(r => setTimeout(r, 250));
  }
  window.scrollTo(0, 0);
  await new Promise(r => setTimeout(r, 500));
  return { height: document.body.scrollHeight, title: document.title };
}"}

