{"function":"() => {
  const out = [];
  document.querySelectorAll('h2').forEach(h => {
    const sec = h.closest('section,div');
    const r = (sec || h).getBoundingClientRect();
    out.push({ title: h.innerText.trim().slice(0,30), top: Math.round(r.top + window.scrollY), height: Math.round(r.height) });
  });
  return { total: document.body.scrollHeight, sections: out };
}"}

